def translate_deployment(page: str) -> str:
    page = page.replace('<html lang="zh-CN">', '<html lang="en">', 1)
    parts = re.split(r'(<script\b[^>]*>.*?</script>|<style\b[^>]*>.*?</style>)', page, flags=re.S | re.I)
    for position in range(0, len(parts), 2):
        for source, target in sorted(LABELS.items(), key=lambda item: len(item[0]), reverse=True):
            parts[position] = parts[position].replace(source, target)
    page = ''.join(parts)
    page = page.replace('href="/"', 'href="/en"')
    page = page.replace('href="/deployment" aria-current="page"', 'href="/deployment"', 1)
    page = page.replace('href="/en/deployment" style=', 'href="/en/deployment" aria-current="page" style=', 1)
    runtime = '''<script>(function(){const labels=__LABELS__,phrases=Object.keys(labels).filter(key=>key.length>3).sort((a,b)=>b.length-a.length);function update(node){if(node.nodeType===3){const text=node.nodeValue,trimmed=text.trim();if(labels[trimmed]){node.nodeValue=text.replace(trimmed,labels[trimmed]);return}let translated=text;for(const phrase of phrases)translated=translated.replaceAll(phrase,labels[phrase]);if(translated!==text)node.nodeValue=translated;return}if(node.nodeType!==1||node.closest('script,style'))return;const walker=document.createTreeWalker(node,NodeFilter.SHOW_TEXT);while(walker.nextNode())update(walker.currentNode)}const observer=new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)update(node)});observer.observe(document.body,{childList:true,subtree:true});})();</script>'''.replace('__LABELS__', json.dumps(LABELS, ensure_ascii=False))
    return page.replace('</body>', runtime + '</body>', 1)
